            cols.append(c)
    if cols:
        cols=sorted(set(cols))
        ranges=[]
        start=prev=cols[0]
        for col in cols[1:]:
            if col==prev+1:
                prev=col
            else:
                ranges.append((start,prev))
                start=prev=col
        ranges.append((start,prev))
